# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_greek_leg_a import G,H
D=G+[['希腊 dia- + legein → dialegesthai；dialektos','相互、穿过 + 说 → 交谈；说话方式'],['拉丁 dialectus → 法语 dialecte → 英语 dialect','一种语言的地域、群体等变体']]
DC=G+[['希腊 dialektike（techne），接 dialektikos','交谈、问答辩论的技艺'],['拉丁 dialectica → 古法语 dialectique／直接借入英语 dialectic','通过论辩考察观点；不同哲学传统中的辩证法']]
ID=G+[['dialect 等词中的 -lect 被用于近代构词','说话方式、语言变体'],['idio-“个人自己的” + -lect → idiolect','个人语言习惯的整体']]
SO=G+[['近代 socio-“社会群体” + -lect“语言变体”','按社会群体观察说话方式'],['英语 sociolect','社会方言、群体语言变体']]
WB=[
E('dialect','/ˈdaɪəlekt/','方言；某地区或群体的语言变体','同一语言到了不同地方、不同社群，词、语法和发音都可能带上各自的习惯。','希腊 dia-“相互、之间” + legein“说”形成交谈相关词，再经拉丁语、法语成为英语 dialect。',D,'dialect 不只是一种口音：还可以有不同用词和语法。把一种变体叫“语言”还是“方言”，也常受历史、社会身份和政治习惯影响，不能简单拿“标准”“不标准”来排高低。标准语本身也来自特定语言变体。','a regional dialect；a local dialect；speak a dialect；dialect differences。','accent 主要谈发音；dialect 可以同时涵盖发音、词汇和语法。',('The same object has different names in different dialects.','同一种东西在不同方言里有不同名称。'),('The novel preserves features of the local dialect.','小说保留了当地语言变体的一些特点。'),sources=['https://www.etymonline.com/word/dialect','https://en.wiktionary.org/wiki/dialect']),
E('dialectal','/ˌdaɪəˈlektəl/','方言的；属于某种语言变体的','在词旁边贴一个标签：这是某个地方或社群特别常用的说法。','dialect + -al，形成表示“与方言有关”的形容词。',H(D,'英语 dialect + -al → dialectal','语言变体 → 与该变体有关的'),'a dialectal expression 说这个表达有地域或群体特征；dialectal variation 说这些变体之间存在差别。这个标签描述分布，不等于批评“说错了”。是否适合某个正式场合，是另一个语体选择问题。','a dialectal word；dialectal variation；dialectal pronunciation。','dialectal 常指方言；dialectical 在现代学术语境中常指辩证法，不能少看一个音节。',('The dictionary marks the expression as dialectal.','词典把这个表达标为方言用法。'),('The researchers recorded dialectal variation across the region.','研究者记录了整个地区的方言差异。'),sources=['https://en.wiktionary.org/wiki/dialectal','https://www.collinsdictionary.com/dictionary/english/dialectal']),
E('dialectally','/ˌdaɪəˈlektəli/','在方言上；按方言差异而言','从不同地方的人怎样说话这一角度来比较。','dialectal + -ly，表示在语言变体这个层面。',H(D,'英语 dialect → dialectal → dialectally','语言变体 → 方言的 → 在方言层面'),'a dialectally restricted word 只在某些语言变体中常用。dialectally diverse 则说不同社群或地区的说法丰富。它并不说明这些人彼此必定听不懂，差异可以大，也可以很细微。','dialectally restricted；dialectally diverse；vary dialectally。','dialectally 关注方言差异；dialectically 多指从辩证关系出发，两者容易因拼写近而混淆。',('The word is dialectally restricted.','这个词只用于某些方言。'),('The area is linguistically and dialectally diverse.','这个地区的语言及方言种类丰富。'),sources=['https://www.merriam-webster.com/dictionary/dialectally','https://en.wiktionary.org/wiki/dialectally']),
E('dialectology','英 /ˌdaɪəlekˈtɒlədʒi/；美 /ˌdaɪəlekˈtɑːlədʒi/','方言学','把各地、各群体怎样说话收集起来，比较差别怎样分布、怎样变化。','dialect + 连接元音 -o- + -logy“研究”。',H(D,'英语 dialect + -o- + -logy → dialectology','语言变体 + 研究 → 方言学'),'dialectology 会研究发音、词汇和语法，常用录音、访谈、地图和语料比较。它不是只收集“奇怪说法”，而是把不同变体当成有规律的语言系统。传统地域研究与社会因素研究也会相互联系。','research in dialectology；a course in dialectology；historical dialectology。','dialectology 以语言变体为中心；phonetics 以语音的发出、传递和感知为中心，两者有交叉但不等同。',('Her interest in dialectology began with local place names.','她对方言学的兴趣始于当地地名。'),('Dialectology can reveal patterns of language change.','方言学可以揭示语言变化的规律。'),sources=['https://en.wiktionary.org/wiki/dialectology','https://www.merriam-webster.com/dictionary/dialectology']),
E('dialectologist','英 /ˌdaɪəlekˈtɒlədʒɪst/；美 /ˌdaɪəlekˈtɑːlədʒɪst/','方言学家、方言研究者','带着问题去听不同人说话，再把观察到的规律拼起来的人。','dialectology 对应 -ist，表示从事这一研究的人。',H(D,'英语 dialectology → dialectologist','方言学 → 方言研究者'),'dialectologist 可以研究一个词在哪里使用、某种语法怎样分布，也可以研究声音变化。只把它解释为“研究地区发音的人”太窄，因为方言差异并不限于口音。','a dialectologist’s fieldwork；a team of dialectologists。','dialectologist 是研究角色；a dialect speaker 是使用某种方言的人。研究者也可能同时是使用者。',('The dialectologist interviewed speakers from several villages.','方言研究者采访了几个村庄的说话者。'),('A dialectologist compared the region’s vocabulary and grammar.','一位方言学家比较了该地区的词汇和语法。'),sources=['https://en.wiktionary.org/wiki/dialectologist','https://www.collinsdictionary.com/dictionary/english/dialectologist']),
E('idiolect','英 /ˈɪdiəʊlekt/；美 /ˈɪdiəlekt/','个人语言习惯；个人语体','每个人都有自己的用词、口头禅、发音和句式组合，像说话留下的个人笔迹。','idio-“个人自己的” + -lect“语言变体”；-lect 从 dialect 等词中抽取后成为构词成分。',ID,'一个人的 idiolect 不是只包含一句口头禅，而是相对独特的语言习惯组合。它会受环境、对象、年龄等影响，也会变化，不能当成永远不变、绝对唯一的身份指纹。','an individual’s idiolect；features of an idiolect；idiolect analysis。','dialect 看群体共享的变体；idiolect 把观察尺度缩到个人。',('The novelist gave each character a distinctive idiolect.','小说家给每个角色安排了独特的个人说话习惯。'),('Her idiolect includes expressions she learned from her grandmother.','她的个人语言习惯中包含从祖母那里学来的表达。'),sources=['https://en.wiktionary.org/wiki/idiolect','https://www.etymonline.com/word/idiolect']),
E('idiolectal','按构词读法，英 /ˌɪdiəʊˈlektəl/；美 /ˌɪdiəˈlektəl/','个人语言习惯的','把注意力放在“这个人特别怎样说”，而不是整个地区怎样说。','idiolect + -al，对应个人语言特点。',H(ID,'英语 idiolect + -al → idiolectal','个人语言习惯 → 与个人语言习惯有关的'),'an idiolectal feature 是个人语言习惯中的一个特征。它可能是偏爱某个词、某种句式或某个发音；一个特征本身不必独一无二，多个习惯的组合才让说话风格显得有个人特点。','idiolectal features；idiolectal variation；idiolectal preferences。','idiolectal 说个人层面；dialectal 常说群体或地区变体层面。二者可以同时影响一句话。',('The study examines the writer’s idiolectal preferences.','研究考察了这位作者个人的用语偏好。'),('This unusual phrase may be an idiolectal feature.','这个不常见的说法可能是个人语言习惯的一种表现。'),sources=['https://www.collinsdictionary.com/dictionary/english/idiolectal','https://en.wiktionary.org/wiki/idiolectal']),
E('sociolect','英 /ˈsəʊsiəʊlekt/；美 /ˈsoʊsiəlekt/','社会方言；社会群体的语言变体','共享某些社会经历的人，可能也共享某些说话方式。','socio-“社会” + -lect“语言变体”。',SO,'sociolect 可以讨论与年龄群体、职业圈或其他社会群体相关的语言特征。它说的是可观察的使用模式，不意味着一个群体的所有人都说得完全一样；个人还会随场合切换说法。','a professional sociolect；features of a sociolect；sociolect differences。','regional dialect 主要按地区观察；sociolect 主要按社会群体观察。两种分布会相互交叉。',('The study compares the sociolects of different age groups.','研究比较了不同年龄群体的社会语言变体。'),('Professional vocabulary can form part of a sociolect.','职业词汇可以构成某种社会方言的一部分。'),sources=['https://www.collinsdictionary.com/dictionary/english/sociolect','https://en.wiktionary.org/wiki/sociolect']),
E('sociolectal','按构词读法，英 /ˌsəʊsiəʊˈlektəl/；美 /ˌsoʊsioʊˈlektəl/','社会方言的；与群体语言变体有关的','看到一种说法，考察它与什么社会圈子或经历有关。','sociolect + -al，形成社会方言相关的形容词。',H(SO,'英语 sociolect + -al → sociolectal','社会语言变体 → 与该变体有关的'),'sociolectal variation 说不同社会群体之间的语言变化或差异。研究这类差异时，通常还要考虑地区、场合和个人习惯，不能把一个人的几句话直接当成整个群体的固定特征。','sociolectal variation；sociolectal differences；sociolectal features。','sociolectal 是语言分布的描述，不是对说话者高低、好坏的评价。',('The survey documents sociolectal variation in vocabulary.','调查记录了不同社会群体在词汇使用上的差异。'),('The analyst separated regional and sociolectal features.','分析者区分了地域特征与社会方言特征。'),sources=['https://en.wiktionary.org/wiki/sociolectal','https://www.collinsdictionary.com/dictionary/english/sociolectal']),
E('ethnolect','/ˈeθnəlekt/','族群语言变体','某个族群在共同生活和语言接触中，形成了有特色的一套说法。','ethno-“族群” + -lect“语言变体”。',G+[['近代 ethno- + -lect → ethnolect','族群 + 语言变体 → 与族群相关的语言变体']],'ethnolect 常用于研究族群身份与语言使用的联系。它不是生物遗传出来的说话方式，也不要求群体中的每个人都采用同样特征。接触、迁移和社交网络都可能影响这种变体。','an urban ethnolect；features of an ethnolect；ethnolect research。','ethnolect 是与族群相关的变体；sociolect 是更广的社会群体变体概念。族群身份不能单凭一句话确定。',('The linguist studied an ethnolect used in the city.','语言学家研究了这座城市中的一种族群语言变体。'),('Speakers may shift between an ethnolect and other varieties.','说话者可能在族群语言变体与其他变体之间切换。'),sources=['https://en.wiktionary.org/wiki/ethnolect','https://www.collinsdictionary.com/dictionary/english/ethnolect']),
E('dialectic','/ˌdaɪəˈlektɪk/','辩证法；通过论辩考察观点的方法；相互作用的矛盾关系','把一个观点和对它的质疑摆到一起，让它们互相逼出更清楚的问题。','希腊 dialektike 原说交谈、问答辩论的技艺，经拉丁、法语等借入；不等于现代英语 dialect“方言”加后缀后的唯一含义。',DC,'早期可以从问答论辩理解 dialectic；在不同哲学传统里，它又有特定含义。现代评论中的 a dialectic between freedom and control，常说自由与控制之间不断相互作用的紧张关系。不能把所有用法压成一套固定的三步公式。','the dialectic of；a dialectic between；Socratic dialectic。','dialectic 多谈论辩或矛盾关系；dialect 谈语言变体。两者历史相连，现代核心意思已经分开。',('The seminar explored the dialectic between freedom and responsibility.','研讨课探讨了自由与责任之间相互作用的辩证关系。'),('Questions and objections drive the dialectic forward.','提问与反驳推动论辩继续展开。'),sources=['https://www.etymonline.com/word/dialectic','https://en.wiktionary.org/wiki/dialectic']),
E('dialectical','/ˌdaɪəˈlektɪkəl/','辩证的；通过对立观点与相互关系来考察的','不把两种力量分开摆死，而是看它们怎样影响、限制、改变彼此。','接拉丁 dialecticus“论辩的”的词干与 -al，和 dialectic 同族；英语形容词有自己的历史，不必从较晚的形容词 dialectic 倒推。',G+[['希腊 dialektikos → 拉丁 dialecticus','与交谈、论辩有关的'],['拉丁词干配 -al → 英语 dialectical','论辩的；后来用于不同辩证哲学传统']],'a dialectical approach 常关注对立面怎样相互联系和变化。具体含义取决于作者采用的哲学传统；并不是“任何事情都有好有坏”这一句就能概括。较旧用法也可指方言，但现代说方言通常用 dialectal 更清楚。','a dialectical method；dialectical reasoning；a dialectical relationship。','dialectical 常指辩证的；dialectal 通常指方言的。不要把地方口音分析误写成辩证法分析。',('The essay takes a dialectical approach to social change.','文章用辩证的方法考察社会变化。'),('The course compares different traditions of dialectical reasoning.','课程比较了不同传统中的辩证推理。'),sources=['https://www.etymonline.com/word/dialectical','https://en.wiktionary.org/wiki/dialectical']),
]
